const fs = require('fs');
const GW = 'http://127.0.0.1:8787';
const MOD = 'http://127.0.0.1:5780/webhook/moderation-draft';
const ENV0 = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
// host-side chart renderer (tools/render_viz.py --serve); the n8n
// container has no python/matplotlib. Rootless docker network_mode:host
// is a shared slirp4netns netns - the real host is reached via its
// gateway 10.0.2.2, NOT via loopback (loopback is the netns itself).
const VIZ = ENV0('VIZ_RENDERER_URL') || 'http://10.0.2.2:8791/render';
// an unguarded mkdirSync throw here killed the node before the
// Respond node ran: the webhook caller then saw a bare execution
// failure instead of an in-band {ok:false} refusal row, with zero
// log trail - the same crash-before-Respond pattern the sibling
// nodes already collect (mkdirErrs in Prepare Draft and Handle TG
// Update). Collect the failures and report them once
// log() exists below - the flush append itself stays best-effort
// since the logs dir may be the broken one.
// SYNC-BEGIN: mkdir-collect
const mkdirErrs = [];
for (const d0 of ['/home/node/.n8n/logs', '/home/node/.n8n/state']) {
  try {
    fs.mkdirSync(d0, { recursive: true });
  } catch (e) {
    mkdirErrs.push({ dir: d0,
      error: String((e && e.message) || e).slice(0, 150) });
  }
}
// SYNC-END: mkdir-collect
// best-effort by contract: a transient FS failure must NEVER
// propagate out of log() - logReject's tail append sits on the
// public-gate path, and a throw there would escape the item loop and
// fail the whole webhook execution over a logging problem. Same
// discipline the mkdirErrs flush just above already follows (and
// log()/logCapped in the sibling nodes): logging never breaks the
// flow.
const log = (r) => {
  try {
    fs.appendFileSync('/home/node/.n8n/logs/content-gen.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');
  } catch (e) {}
};
// flush the dir-creation failures collected above: a broken state
// volume still leaves this trail when the log dir itself is writable
for (const m of mkdirErrs) {
  try { log({ action: 'mkdir-failed', dir: m.dir, error: m.error }); }
  catch (e) {}
}
// post registry (issue #12, docs/post-registry-design.md): one
// append-only JSONL lifecycle log every stage writes to. Fail-open
// by contract - a broken state dir, a torn write or an oversized
// event must never block moderation or publish: errors are
// swallowed into this node's own log() and the flow moves on.
// event_id is a deterministic sha1 over the TRANSITION identity
// (post_id|platform|stage|status|writer - deliberately NOT the
// timestamp): a retried transition recomputes ts and dedups to one
// event, while the reader's last-occurrence-wins fold still lands
// on the latest fields. n8n Code nodes only require('fs'), so the
// sha1 rides along inline - same 'no crypto' discipline as the
// padded compares and the preview_v FNV hashes.
// SYNC-BEGIN: registry-event
const registryEvent = (fields) => {
  try {
    if (!fields || !fields.post_id) return;
    const sha1hex = (s) => {
      const bytes = unescape(encodeURIComponent(String(s)));
      const ml = bytes.length;
      const ww = [];
      for (let i = 0; i < ml; i++) {
        ww[i >> 2] = (ww[i >> 2] || 0) |
          (bytes.charCodeAt(i) << (24 - (i % 4) * 8));
      }
      ww[ml >> 2] = (ww[ml >> 2] || 0) |
        (0x80 << (24 - (ml % 4) * 8));
      const wl = (((ml + 8) >> 6) << 4) + 16;
      ww[wl - 1] = ml * 8;
      let h0 = 1732584193, h1 = -271733879, h2 = -1732584194,
        h3 = 271733878, h4 = -1009589776;
      for (let i = 0; i < wl; i += 16) {
        const w = new Array(80);
        for (let j = 0; j < 16; j++) w[j] = ww[i + j] || 0;
        for (let j = 16; j < 80; j++) {
          const x = w[j - 3] ^ w[j - 8] ^ w[j - 14] ^ w[j - 16];
          w[j] = (x << 1) | (x >>> 31);
        }
        let a = h0, b = h1, c = h2, d = h3, e = h4;
        for (let j = 0; j < 80; j++) {
          const f = j < 20 ? (b & c) | (~b & d)
            : j < 40 ? b ^ c ^ d
            : j < 60 ? (b & c) | (b & d) | (c & d)
            : b ^ c ^ d;
          const k = j < 20 ? 1518500249
            : j < 40 ? 1859775393
            : j < 60 ? -1894007588 : -899497514;
          const t = (((a << 5) | (a >>> 27)) + f + e + k + w[j]) | 0;
          e = d; d = c; c = ((b << 30) | (b >>> 2)) | 0; b = a; a = t;
        }
        h0 = (h0 + a) | 0; h1 = (h1 + b) | 0;
        h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
        h4 = (h4 + e) | 0;
      }
      return [h0, h1, h2, h3, h4]
        .map((h) => ('00000000' + (h >>> 0).toString(16)).slice(-8))
        .join('');
    };
    const ev = {
      schema_v: 1,
      post_id: String(fields.post_id),
      draft_id: String(fields.draft_id || ''),
      platform: String(fields.platform || ''),
      stage: String(fields.stage || ''),
      status: String(fields.status || ''),
      ts: new Date().toISOString(),
      writer: String(fields.writer || '')
    };
    ev.event_id = sha1hex(ev.post_id + '|' + ev.platform + '|' +
      ev.stage + '|' + ev.status + '|' + ev.writer);
    if (fields.error) ev.error = String(fields.error).slice(0, 300);
    if (fields.maybe_live === true) ev.maybe_live = true;
    if (Array.isArray(fields.external_ids) && fields.external_ids.length) {
      ev.external_ids = fields.external_ids.map(String);
    }
    if (fields.published_at) ev.published_at = String(fields.published_at);
    // O_APPEND keeps concurrent single-line appends intact only
    // while a line stays under PIPE_BUF (4KB, ~3.5KB used as the
    // conservative cap). Shrink in the spec'd order - error text
    // first, external_ids to its first element, then maybe_live;
    // the required fields and published_at are never dropped.
    let oversized = false;
    let line = JSON.stringify(ev) + '\n';
    if (line.length > 3500) {
      oversized = true;
      if (ev.error) ev.error = ev.error.slice(0, 120);
      line = JSON.stringify(ev) + '\n';
    }
    if (line.length > 3500 && ev.external_ids &&
        ev.external_ids.length > 1) {
      ev.external_ids = ev.external_ids.slice(0, 1);
      line = JSON.stringify(ev) + '\n';
    }
    if (line.length > 3500 && ev.maybe_live) {
      delete ev.maybe_live;
      line = JSON.stringify(ev) + '\n';
    }
    if (oversized) {
      try {
        log({ action: 'registry_event_oversized',
          post_id: ev.post_id, stage: ev.stage });
      } catch (e) {}
    }
    fs.mkdirSync('/home/node/.n8n/state/registry', { recursive: true });
    fs.appendFileSync('/home/node/.n8n/state/registry/events.jsonl', line);
  } catch (e) {
    try {
      log({ action: 'registry_append_failed',
        error: String(e).slice(0, 150) });
    } catch (e2) {}
  }
};
// SYNC-END: registry-event
// public-gate reject logging is attacker-spammable: one forged POST =
// one log append, so an unbounded log() per rejection lets a bot
// inflate content-gen.jsonl forever. Keep the first few rejects
// verbatim, then log once per ~100 rejects carrying the running
// total so the suppressed ones stay visible in the count
// (exact under bounded-append counting - see logReject). The counter
// lives in a state file - Code-node locals do not survive between
// executions.
// tmp+rename like every other state write in the sibling Code nodes
// (logCapped in Handle TG Update, the sp-publish counters): a crash
// mid-writeFileSync would leave a torn counter JSON - harmless for
// the suppress-count itself, but there is no reason to keep the one
// plain writeFileSync in the system.
// SYNC: sibling copies live in Publish Tick (sp-publish, hardened
// 0o600 variant), Handle TG Update, Prepare Draft and Compose
// Message (sp-tg-moderation) and Resolve Chat + Webhook (sp-tg-setup).
// n8n Code nodes cannot share a prelude - replicate any fix to every
// copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic
const REJECT_CTR = '/home/node/.n8n/state/cg-auth-rejects.json';
const logReject = (rec) => {
  // Bounded-append counter - same design as logCapped in Handle TG
  // Update (sp-tg-moderation), SYNC any fix to both. Each reject
  // appends ONE byte to a companion tick file; the count is the
  // persisted base in REJECT_CTR ({n}) plus the tick file's byte
  // length. Appends are O_APPEND-atomic, so parallel executions
  // cannot silently lose rejects the way the old read -> draw ->
  // write leap could, and the persisted count is exact. Write
  // amplification stays bounded at one small append per reject (no
  // read-modify-write) plus a fold every FOLD_AT ticks: the base is
  // persisted with tmp+rename and the tick file truncated, so
  // neither file grows past ~1KB. A fold racing a concurrent append
  // can still drop the few ticks written inside its
  // stat -> truncate window - a bounded loss on a spam-suppress
  // counter, not an audit trail.
  // SYNC-BEGIN: bounded-append
  const FOLD_AT = 1000;
  const ticks = REJECT_CTR + '.ticks';
  let base = 0;
  try { base = JSON.parse(fs.readFileSync(REJECT_CTR, 'utf8')).n || 0; } catch (e) {}
  let t = 0;
  try { t = fs.statSync(ticks).size; } catch (e) {}
  try { fs.appendFileSync(ticks, '.'); } catch (e) {}
  const n = base + t + 1;
  if (t + 1 >= FOLD_AT) {
    // fold the tick bytes into the base counter, then clear the
    // tick file - bounds its growth while keeping the total
    try {
      writeJsonAtomic(REJECT_CTR, { n: n });
      fs.truncateSync(ticks);
    } catch (e) {}
  }
  if (n <= 5 || Math.floor((n - 1) / 100) !== Math.floor(n / 100)) {
    log({ ...rec, rejects_seen: n });
  }
};
// SYNC-END: bounded-append
// Every secret this node hands to helpers.httpRequest lands in
// SECRET_VALUES: a thrown request error can serialize the request
// config - the X-Shared-Token header on the moderation-draft
// dispatch (DRAFT_WEBHOOK_SECRET), the bot token inside the
// sendMessage URL - into content-gen.jsonl or the webhook
// response, where it persists in plain text. Error strings
// therefore pass through scrubSecrets() before they are logged
// or returned. Same masking discipline as KNOWN_TOKENS/scrub in
// sp-publish, scrubSecrets in Handle TG Update (sp-tg-moderation)
// and SECRET_VALUES in sp-tg-setup; the >=8 length floor avoids
// shredding unrelated message text.
const SECRET_VALUES = [];
for (const sn of ['DRAFT_WEBHOOK_SECRET', 'TELEGRAM_BOT_TOKEN',
  'CONTENT_GEN_WEBHOOK_SECRET']) {
  const sv = ENV0(sn);
  if (sv && sv.length >= 8) SECRET_VALUES.push(sv);
}
// SYNC-BEGIN: scrub-secrets
const scrubSecrets = (s) => {
  let out = String(s);
  for (const v of SECRET_VALUES) {
    if (v && v.length >= 8) out = out.split(v).join('***');
  }
  return out;
};
// SYNC-END: scrub-secrets
const run = (role, input, systemExtra) => this.helpers.httpRequest({
  method: 'POST', url: GW + '/run',
  body: { role: role, input: input, ...(systemExtra ? { system_extra: systemExtra } : {}) },
  json: true, timeout: 300000
});

// brief-gate telegram notify - same env/state contract as sp-tg-moderation
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const notify = async (text) => {
  try {
    // operator chat_id is pinned config, env-first like the sibling
    // nodes (sp-publish, Handle TG Update): TELEGRAM_CHAT_ID wins,
    // the tg.json sp-tg-setup writes is the compat fallback
    const chatId = ENV('TELEGRAM_CHAT_ID') || (() => {
      try {
        return JSON.parse(fs.readFileSync('/home/node/.n8n/state/tg.json', 'utf8')).chat_id;
      } catch (e) { return null; }
    })();
    if (!chatId || !ENV('TELEGRAM_BOT_TOKEN')) return;
    // SYNC-BEGIN: tg-timeout
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + ENV('TELEGRAM_BOT_TOKEN') + '/sendMessage',
      body: { chat_id: chatId, text: text },
      json: true,
      // explicit 30s timeout like the sibling tg() helpers:
      // helpers.httpRequest is unbounded by default, so a hung
      // api.telegram.org socket would stall the generation run
      timeout: 30000
    });
    // SYNC-END: tg-timeout
  } catch (e) { log({ stage: 'notify', error: scrubSecrets(e).slice(0, 300) }); }
};

// anti-slop filter: banned phrases (EN + RU), emoji bullets, thin entity usage
const BANNED = [/\bdelve\b/i, /\bleverage\b/i, /\btapestry\b/i, /game-?changer/i,
  /excited to announce/i, /fast-?paced world/i, /\bunlock\b/i, /\belevate\b/i,
  /\bsynergy\b/i, /\bdelve into\b/i,
  // article lexicon (docs/content-article-spec.md) - only unambiguous
  // slop terms; 'harness'/'beacon' and the RU unique/revolutionary
  // adjectives stay prompt-level bans because they have legit
  // technical uses ('test harness', 'unique index') a regex cannot
  // tell from slop
  /\bunleash\b/i, /\bseamless\b/i, /\bsupercharg/i, /\bsymphony\b/i,
  /\btestament\b/i, /ever-?evolving/i, /let'?s dive in/i,
  /\u0433\u043e\u0431\u0435\u043b\u0435\u043d/i, /\u0441\u0438\u043c\u0444\u043e\u043d\u0438/i,
  /\u0431\u044b\u0441\u0442\u0440\u043e \u043c\u0435\u043d\u044f\u044e\u0449\u0435\u043c\u0441\u044f \u043c\u0438\u0440\u0435/i,
  /\u0431\u0435\u0437 \u043b\u0438\u0448\u043d\u0438\u0445 \u0441\u043b\u043e\u0432/i,
  /\u043f\u043e\u0434\u043d\u044f\u0442\u044c \u043d\u0430 \u043d\u043e\u0432\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c/i,
  /\u0432 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u043c \u043c\u0438\u0440\u0435/i, /\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0440\u0430\u0437\u0431\u0435\u0440\u0451\u043c/i, /\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0440\u0430\u0437\u0431\u0435\u0440\u0435\u043c/i,
  /\u043f\u043e\u0433\u0440\u0443\u0437\u0438\u043c\u0441\u044f/i, /\u043d\u0435 \u0441\u0435\u043a\u0440\u0435\u0442,? \u0447\u0442\u043e/i, /\u0432\u0430\u0436\u043d\u043e \u043e\u0442\u043c\u0435\u0442\u0438\u0442\u044c/i,
  /(^|[^\u0430-\u044f\u0451a-z])\u0432\u0430\u0436\u043d\u043e([^\u0430-\u044f\u0451a-z]|$)/i,
  /(^|[^\u0430-\u044f\u0451a-z])\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e([^\u0430-\u044f\u0451a-z]|$)/i,
  /(^|[^\u0430-\u044f\u0451a-z])\u043c\u0435\u043b\u043e\u0447\u044c([^\u0430-\u044f\u0451a-z]|$)/i];
const EMOJI_BULLET = /^\s*[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u;
const humanize = (t) => String(t)
  .replace(/[\u2014\u2013]/g, '-')
  .replace(/[\u200B-\u200F\uFEFF\u2060]/g, '')
  .replace(/[\u201C\u201D\u201E]/g, '"')
  .replace(/[\u2018\u2019\u201A]/g, "'")
  .replace(/\u2026/g, '...')
  .replace(/\u00A0/g, ' ')
  .replace(/[ \t]+\n/g, '\n')
  .trim();

// SYNC: the keys of this MAP are the third copy of the platform list
// the enabled-platforms gate blocks carry (Publish Tick / Handle TG
// Update): a platform added here but not to ALL_PLATFORMS generates
// drafts every gate parks in skipped/ forever, so check_sync
// compares the platform-token SET across all three copies - the
// writer-* role values may evolve freely, the keys may not.
// SYNC-BEGIN: enabled-platforms
const MAP = {
  linkedin: ['writer-linkedin'],
  facebook: ['writer-fb'], fb: ['writer-fb'],
  vk: ['writer-vk'],
  habr: ['writer-habr'],
  all: ['writer-linkedin', 'writer-fb', 'writer-vk', 'writer-habr']
};
// SYNC-END: enabled-platforms

// shared-secret gate: content-gen is reachable through the public
// edge proxy like moderation-draft, and the draft dispatch below
// carries the real DRAFT_WEBHOOK_SECRET - so a forged POST here made
// the workflow itself push attacker text (with a live Approve button)
// into the operator chat, plus free LLM spend. Callers must send an
// X-Content-Gen-Secret header matching CONTENT_GEN_WEBHOOK_SECRET.
// Checked BEFORE the brief gate or any LLM call - the whole request
// is untrusted until the secret passes. Fails closed when the env is
// unset: a dead endpoint beats an open spend path. Constant-time-ish
// compare without crypto (only fs is allowed in Code nodes).
// SYNC: identical padded compares live in Handle TG Update's and
// Prepare Draft's secretOk (sp-tg-moderation, TG_WEBHOOK_SECRET and
// DRAFT_WEBHOOK_SECRET gates) - n8n Code nodes cannot share a
// prelude, so replicate any fix to all three copies.
const CG_SECRET = ENV0('CONTENT_GEN_WEBHOOK_SECRET');
// SYNC-BEGIN: padded-compare
const cgSecretOk = (got) => {
  const a = String(got == null ? '' : got);
  if (!CG_SECRET) return false;
  // no early return on a length mismatch: it leaks the expected
  // secret length through response timing on this public endpoint.
  // Pad both operands to a shared length and fold the length delta
  // into diff so a padded tail can never compare equal. The first
  // loop count is a FIXED 64 - a bound of SECRET.length would make
  // the compare cost proportional to the secret's length, the very
  // leak the floor exists to hide, and a.length stays OUT of every
  // bound so an over-long attacker header cannot stretch the compare
  // either. Positions past 64 are NOT ignored: the second loop folds
  // the tail for i < SECRET.length (a per-deployment constant), so a
  // >64 configured secret compares in full instead of degrading to a
  // prefix-only check. padEnd never truncates, and charCodeAt past
  // the end of pa yields NaN (folds as 0 ^ pb char - still a nonzero
  // diff); the length-xor above rejects whatever length mismatch is
  // left.
  const len = 64;
  const pa = a.padEnd(len, '\0');
  const pb = CG_SECRET.padEnd(len, '\0');
  let diff = a.length ^ CG_SECRET.length;
  for (let i = 0; i < len; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  for (let i = len; i < CG_SECRET.length; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  return diff === 0;
};
// SYNC-END: padded-compare

// perf-informed generation (issue #64): Analytics Tick writes
// perf_summary.json every 6h - the top posts by engagement over its
// sliding window, engagement-sorted already. Read ONCE per execution;
// each writer brief below picks up to 5 entries matching the writer's
// platform as top_performers. FAIL-OPEN by contract - a missing,
// corrupt or unreadable file must never block generation, so the skip
// is logged and the run continues with an empty list.
const PERF_SUMMARY = '/home/node/.n8n/state/analytics/perf_summary.json';
let perfPosts = [];
let perfSkip = null;
try {
  const ps = JSON.parse(fs.readFileSync(PERF_SUMMARY, 'utf8'));
  if (ps && Array.isArray(ps.posts)) {
    perfPosts = ps.posts;
  } else {
    perfSkip = 'no posts[] in perf_summary.json';
  }
} catch (e) {
  perfSkip = (e && e.code === 'ENOENT')
    ? 'perf_summary.json not found'
    : 'perf_summary.json unreadable: ' +
      String((e && e.message) || e).slice(0, 120);
}
if (perfSkip) log({ action: 'perf-summary', skipped: perfSkip });
let perfMatched = 0;
let perfDelivered = 0;
// writer role -> platform keys, the reverse of the MAP relation above
// ('all' is a fan-out token, not a platform key): writer-vk -> ['vk'],
// writer-fb -> ['facebook', 'fb'] since registry events may carry
// either spelling (sp-publish's PLATFORM_ALIAS folds facebook -> fb).
const rolePlats = {};
for (const p of Object.keys(MAP)) {
  if (p === 'all') continue;
  for (const r of MAP[p]) {
    (rolePlats[r] = rolePlats[r] || []).push(p);
  }
}

const results = [];
for (const item of $input.all()) {
  // the webhook node passes request headers through on
  // item.json.headers (lowercased names). Reject before the brief
  // gate or any LLM call - a refused call answers {ok:false} in-band
  // and nothing is generated, logged upstream or dispatched onward.
  const hdrs = (item.json && item.json.headers) || {};
  if (!cgSecretOk(hdrs['x-content-gen-secret'])) {
    logReject({ stage: 'auth', ok: false,
      reason: CG_SECRET
        ? 'missing/invalid x-content-gen-secret'
        : 'CONTENT_GEN_WEBHOOK_SECRET not configured - failing closed' });
    results.push({ platform: null, ok: false, stage: 'auth',
      error: CG_SECRET
        ? 'unauthorized - missing/invalid content-gen webhook secret'
        : 'unauthorized - CONTENT_GEN_WEBHOOK_SECRET not configured (fails closed)' });
    continue;
  }
  const b = item.json.body || item.json;
  const platform = String(b.platform || 'all').toLowerCase();
  const topic = b.topic || '';
  const rawContext = String(b.context || '');
  const context = [
    'Topic: ' + topic,
    b.mode === 'rewrite' ? 'Rewrite request. Editor feedback: ' + (b.feedback || '') : '',
    'Raw context:', rawContext
  ].filter(Boolean).join('\n');

  // `platform` may carry a comma-separated enabled list (the 'post N'
  // dispatch in sp-tg-moderation sends PUBLISH_PLATFORMS verbatim,
  // e.g. 'vk,linkedin'). Expand ONLY known keys through MAP and
  // dedupe - 'all' (also the platform default above) still fans out
  // via MAP.all. The old MAP.all fallback for unmapped values turned
  // a verbatim 'instagram' in PUBLISH_PLATFORMS into a fan-out to
  // every writer, producing drafts no platform could ever approve -
  // and a mixed list silently dropped the unmapped platform. Now
  // unknown tokens are collected, skipped, and reported to the
  // operator; an entirely unmapped request short-circuits here,
  // before the brief gate and any LLM spend.
  const platTokens = platform.split(',')
    .map((p) => p.trim()).filter(Boolean);
  const unknownPlats = platTokens.filter((p) => !MAP[p]);
  const roleList = [...new Set(platTokens.flatMap((p) => MAP[p] || []))];
  if (unknownPlats.length) {
    log({ stage: 'platform-map', skipped: unknownPlats, topic: topic });
    await notify('platform ' + unknownPlats.join(', ') +
      ' has no writer/driver - skipped' +
      (topic ? ' (' + topic + ')' : ''));
  }
  if (!roleList.length) {
    results.push({ platform: platform, ok: false, stage: 'platform-map',
      error: 'no known platform in request - \'' +
        (platTokens.join('\', \'') || '(empty)') +
        '\' has no writer/driver' });
    continue;
  }

  // Brief gate (source > brief > draft): write only from supplied material.
  // Missing/thin context (<200 chars) or context without fact-like
  // tokens (>=2 tokens containing a digit) = refuse, no LLM calls.
  // Skipped for mode==='rewrite': an Edit dispatch rewrites the existing
  // draft - the previous draft text IS the material, so a short draft or
  // one without digit-bearing tokens is a valid rewrite target, not a
  // thin brief. Gating it made the Edit flow uncompletable for exactly
  // those drafts.
  const factTokens = rawContext.match(/\S*\d\S*/g) || [];
  if (b.mode !== 'rewrite' &&
      (rawContext.trim().length < 200 || factTokens.length < 2)) {
    const why = rawContext.trim().length < 200 ? 'short-context' : 'no-facts';
    log({ stage: 'brief-gate', reason: why, topic: topic });
    await notify('no material in brief' + (topic ? ' (' + topic + ')' : '') +
      ' - generation skipped [' + why + ']');
    results.push({ platform: platform, ok: false, stage: 'brief-gate',
      error: 'no material in brief (' + why + ')' });
    continue;
  }

  // brief meta: explicit payload fields win; else read from serialized
  // brief JSON inside context (links[]/scope/accents[] per brief schema)
  let briefMeta = {};
  try {
    const c = JSON.parse(rawContext);
    if (c && typeof c === 'object' && !Array.isArray(c)) briefMeta = c;
  } catch (e) { /* context is raw text, not a serialized brief */ }
  const scope = String(b.scope || briefMeta.scope || '');
  const accents = Array.isArray(b.accents) ? b.accents.map(String)
    : (Array.isArray(briefMeta.accents) ? briefMeta.accents.map(String) : []);
  const links = Array.isArray(b.links) ? b.links
    : (Array.isArray(briefMeta.links) ? briefMeta.links : []);

  // session posts get GENERATED charts instead of archive photos:
  // viz_data[] datasets from the brief are drawn by the host renderer.
  const vizData = Array.isArray(b.viz_data) ? b.viz_data
    : (Array.isArray(briefMeta.viz_data) ? briefMeta.viz_data : []);
  const srcType = String(b.source_type || briefMeta.source_type || '');
  const sessionViz = srcType === 'session' || vizData.length > 0;
  // generated-image path: explicit payload flag gen_image, or a
  // non-retro non-session source_type (hype/hot-topic/news). Session
  // posts keep generated charts; retro/archive and untyped posts keep
  // the archive-photo media-selector path.
  const genImage = b.gen_image === true || b.gen_image === 'true'
    || briefMeta.gen_image === true;
  const genImagePath = !sessionViz && (genImage ||
    (srcType !== '' && srcType !== 'retro' && srcType !== 'archive'));
  // one draft id per produced draft so viz PNGs (named <draft_id>_*.png)
  // map 1:1 to moderation drafts; multi-platform runs get a role suffix
  const draftIdBase = String(b.draft_id ||
    ('d' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6)));
  // canonical post_id (issue #12): minted HERE at fan-out - this is the
  // only point where 'these platform drafts belong together' is known.
  // Format p_<epoch>_<rand6> per docs/post-registry-design.md. A
  // caller-supplied post_id (the Edit rewrite path reuses the draft's
  // own one so the rewrite lands under the same post) is accepted only
  // in the allowlisted charset - the id rides the public webhook body,
  // lands in draft/queue JSON and Telegram preview text.
  const postId = /^p_[A-Za-z0-9_-]{1,56}$/.test(String(b.post_id || ''))
    ? String(b.post_id)
    : 'p_' + Math.floor(Date.now() / 1000) + '_' +
      Math.random().toString(36).slice(2, 8);

  // Pass 1 - fact extraction (Gemini Flash via llm-gateway)
  let facts = {};
  try {
    const r = await run('extract-facts', context);
    facts = r.json || JSON.parse(r.text);
  } catch (e) {
    log({ stage: 'extract', error: scrubSecrets(e).slice(0, 300) });
    results.push({ platform: platform, ok: false, stage: 'extract', error: scrubSecrets(e).slice(0, 300) });
    continue;
  }

  // Pass 2 - platform writers (Gemini via llm-gateway, per-manifest
  // model fallback chain). roleList was resolved above the brief
  // gate: known platform tokens only, unknown ones already reported
  // to the operator there.
  for (const role of roleList) {
    // moderation-draft caps draft_id at 40 chars (the Telegram
    // callback_data budget in Prepare Draft), and a long
    // caller-supplied base plus the '-<platform>' suffix would cross
    // it and get the draft refused at delivery. Truncate the BASE so
    // base+suffix stays <=40 - never the suffix, which is what keeps
    // the per-platform ids distinct inside one multi-platform run.
    // A >40 base on a single-platform run is left untouched on
    // purpose: moderation-draft's explicit reject beats a silently
    // renamed draft id.
    const roleSfx = '-' + role.replace('writer-', '');
    const itemDraftId = roleList.length > 1
      ? draftIdBase.slice(0, 40 - roleSfx.length) + roleSfx
      : draftIdBase;
    // up to 5 top performers on THIS writer's platform (perfPosts is
    // already engagement-sorted by Analytics Tick), trimmed to the
    // reference fields the writer prompts document - nulls dropped
    const platsForRole = rolePlats[role] || [role.replace('writer-', '')];
    const topPerf = perfPosts
      .filter((pp) => pp &&
        platsForRole.indexOf(String(pp.platform || '')) !== -1)
      .slice(0, 5)
      .map((pp) => {
        const t = {};
        if (pp.post_id != null) t.post_id = String(pp.post_id);
        if (pp.external_id != null) t.external_id = String(pp.external_id);
        if (pp.views != null) t.views = pp.views;
        if (pp.engagement != null) t.engagement = pp.engagement;
        return t;
      });
    perfMatched += topPerf.length;
    const brief = JSON.stringify({
      topic: topic, mode: b.mode || 'new', feedback: b.feedback || null,
      scope: scope || null, accents: accents, links: links, facts: facts,
      // empty topPerf keeps the payload byte-identical to the
      // pre-perf brief - the field is optional input for the writers
      ...(topPerf.length ? { top_performers: topPerf } : {})
    });
    let text = '', parsed = null, warnings = [];
    let mediaSel = { selected: [], caption_note: '' };
    try {
      let r = await run(role, brief);
      parsed = r.json || JSON.parse(r.text);
      text = parsed.text || '';
      // anti-slop check, then one rewrite pass with violation feedback
      let violations = BANNED.filter(rx => rx.test(text)).map(rx => rx.source);
      if (text.split('\n').some(l => EMOJI_BULLET.test(l))) violations.push('emoji-bullet');
      const ents = [...(facts.stack || []), ...(facts.metrics || [])].map(String);
      if (ents.filter(e => e && text.toLowerCase().includes(e.toLowerCase())).length < 2) {
        violations.push('thin-entities');
      }
      if (violations.length) {
        r = await run(role, brief,
          'Rewrite fixing violations: ' + violations.join(', ') + '. Keep the same JSON output format.');
        parsed = r.json || JSON.parse(r.text);
        text = parsed.text || '';
      }
      // Pass 3 - deterministic humanizer
      text = humanize(text);
      if (parsed) parsed.text = text;

      // Pass 4 - verifier: critic checks draft against brief facts/scope.
      // Invented claims -> one rewrite attempt -> final warnings still go
      // to moderation with the draft.
      // issue #52: the critic used to receive {draft} only - numbers and
      // labels inside the writer's visuals[] datasets (timelines,
      // matrices, metric charts) bypassed fact-checking entirely, so
      // 'every number traces to facts' was prompt-level only for
      // diagrams. Each visual's checkable claims are flattened into one
      // compact line ('visual k <type>/<block> "title": key=value; ...')
      // appended to the payload: scalars keep their key, scalar lists
      // fold into one claim ('values=4|5|6') and object lists unfold per
      // element so each milestone/row keeps its own keys. visualClaims()
      // reads `parsed` INSIDE verifyInput so a verifier-driven rewrite
      // (which may swap visuals[] wholesale) is verified on ITS
      // datasets, not the pre-rewrite ones.
      const flatClaims = (node, key, out, depth) => {
        if (node == null || out.length >= 40 || depth > 6) return;
        if (typeof node !== 'object') {
          const s = String(node).trim().slice(0, 80);
          if (s) out.push((key ? key + '=' : '') + s);
          return;
        }
        if (Array.isArray(node)) {
          if (node.every((x) => x == null || typeof x !== 'object')) {
            const s = node.slice(0, 20)
              .map((x) => String(x).trim()).filter(Boolean)
              .join('|').slice(0, 160);
            if (s) out.push((key ? key + '=' : '') + s);
            return;
          }
          for (const x of node.slice(0, 16)) flatClaims(x, null, out, depth + 1);
          return;
        }
        for (const k of Object.keys(node).slice(0, 16)) {
          flatClaims(node[k], k, out, depth + 1);
        }
      };
      const visualClaims = () =>
        (parsed && Array.isArray(parsed.visuals) ? parsed.visuals : [])
          .map((v, i) => {
            const claims = [];
            flatClaims(v && typeof v === 'object' && v.dataset
              ? v.dataset.data : null, null, claims, 0);
            const head = 'visual ' + (i + 1) + ' ' +
              String((v && v.type) || '?') +
              (v && v.block ? '/' + String(v.block) : '') +
              (v && v.title ? ' "' + String(v.title).slice(0, 60) + '"' : '');
            // the caption is a checkable claim in BOTH cases: a
            // visual with a dataset used to send only its dataset
            // claims, so the caption text bypassed the critic
            if (v && v.caption) {
              claims.push('caption=' + String(v.caption).slice(0, 120));
            }
            return (head + ': ' +
              (claims.join('; ') || '(no claims)')).slice(0, 640);
          });
      const verifyInput = (t) => {
        const vs = visualClaims();
        return JSON.stringify({
          topic: topic, platform: role.replace('writer-', ''),
          scope: scope || null, accents: accents, links: links,
          facts: facts, draft: t,
          // 'visuals' stays absent on an empty task list - non-article
          // drafts keep the byte-identical legacy payload
          ...(vs.length ? { visuals: vs } : {})
        });
      };
      const issueText = (i) => ((i.type || 'issue') + ': ' + (i.detail || '')).slice(0, 200);
      try {
        let vr = await run('critic', verifyInput(text));
        let ver = vr.json || JSON.parse(vr.text);
        let issues = Array.isArray(ver.issues) ? ver.issues : [];
        const blocking = issues.filter(i => i.type === 'fact' || i.type === 'scope');
        if (ver.verdict === 'reject' || blocking.length) {
          const fixList = issues.map(issueText).join('; ') || ver.one_line || 'verdict reject';
          const r2 = await run(role, brief,
            'Verifier flagged invented or out-of-scope content: ' + fixList +
            '. Rewrite using ONLY the supplied facts and links, stay inside scope. ' +
            'Keep the same JSON output format.');
          const p2 = r2.json || JSON.parse(r2.text);
          if (p2 && p2.text) { parsed = p2; text = humanize(p2.text); parsed.text = text; }
          const vr2 = await run('critic', verifyInput(text));
          ver = vr2.json || JSON.parse(vr2.text);
          issues = Array.isArray(ver.issues) ? ver.issues : [];
          warnings = issues.map(issueText);
          if (ver.verdict === 'reject' && !warnings.length) {
            warnings.push('verifier verdict: reject - ' + (ver.one_line || 'no detail'));
          }
          log({ stage: 'verify', role: role, verdict: ver.verdict, rewritten: true,
            warnings: warnings.length });
        } else {
          // non-blocking issues (voice/format/slop) still reach the moderator
          warnings = issues.map(issueText);
          log({ stage: 'verify', role: role, verdict: ver.verdict, rewritten: false,
            warnings: warnings.length });
        }
      } catch (e) {
        log({ stage: 'verify', role: role, error: scrubSecrets(e).slice(0, 300) });
        warnings = ['verifier unavailable - draft not fact-checked'];
      }

      // Pass 5 - media. Article visuals (writer's parsed.visuals)
      // render first, then three legacy paths fill the rest:
      //  a) session posts (source_type=session or viz_data present):
      //     GENERATED charts. viz-spec picks 0-2 specs referencing
      //     viz_data[] ids, the host render daemon draws PNGs into
      //     materials/viz/ and returns paths for sendPhoto. Render
      //     failures degrade to text-only - the draft still moderates.
      //  b) generated-image posts (gen_image:true in the payload, or a
      //     non-retro non-session source_type like hype/hot-topic):
      //     the image-gen role emits 1-2 text-to-image prompts
      //     tailored to the draft accents, llm-gateway /image renders
      //     each via a Gemini image model into materials/img/ and
      //     returns paths for sendPhoto. Failures degrade to
      //     text-only.
      //  c) other posts (retro/archive, untyped): media-selector
      //     picks 0-2 files from media[] candidates as before.
      //  d) article skeleton visuals (docs/content-article-spec.md):
      //     the writer's parsed.visuals[] is a per-block viz task
      //     list read off the FINAL parsed object (a critic rewrite
      //     may have swapped it). Chart-typed tasks carry an INLINE
      //     dataset ({kind, data} - the writer never sees viz_data)
      //     and render through the same host renderer as session
      //     charts via synthetic viz_data ids; 'image' tasks go to
      //     the gateway image path. Article visuals render FIRST
      //     (B3 timeline + B4 topology are mandatory per the spec),
      //     then the legacy paths below fill the slots left free up
      //     to MEDIA_MAX. Tasks without a usable dataset/prompt are
      //     dropped, and every render failure still degrades to
      //     text-only - but never silently (issue #51): the dropped
      //     figure loses its '[See Fig N]' pointer and reports a
      //     warnings[] line onto the moderation card.
      const MEDIA_MAX = 4;
      const room = () => Math.max(0, MEDIA_MAX - mediaSel.selected.length);
      {
        // Fig bookkeeping (issue #51): the writer numbers its
        // '[See Fig N]' / '[см. Fig N]' pointers by the 1-based index
        // over visuals[] as REQUESTED, but renders attach in
        // mediaSel.selected order - which is neither the requested
        // order (the chart batch lands before the image calls) nor
        // complete (failed tasks dropped silently, leaving dangling
        // pointers). Results are therefore collected per task first
        // and attached afterwards in requested order, so the pushed
        // index IS the final figure number; the pointers are then
        // rewritten to match, and every task that attached nothing
        // drops its pointer and earns a warnings[] line that lands
        // on the moderation card's [WARNINGS] block.
        const artTasks = (parsed && Array.isArray(parsed.visuals)
          ? parsed.visuals : []);
        const taskLabel = {};   // reqN -> 'type/block "title"'
        const artFail = {};     // reqN -> why nothing attached
        const pathByN = {};     // reqN -> rendered path
        const chartSlots = [];  // {n, vid} in artSpecs order
        const artSpecs = [];
        const artData = [];
        const artImgs = [];     // {n, prompt} in visuals[] order
        // chart tasks keep their old MEDIA_MAX priority (the batch
        // runs before the image calls, and mandatory B3/B4 diagrams
        // should not lose slots to a decorative hero); image tasks
        // render into whatever room the chart successes leave
        let chartBudget = room();
        for (let vi = 0; vi < artTasks.length; vi++) {
          const n = vi + 1;
          const v = artTasks[vi];
          if (!v || typeof v !== 'object') {
            taskLabel[n] = '?/?';
            artFail[n] = 'non-object visuals[] entry';
            continue;
          }
          const label = String(v.type || '?') + '/' +
            String(v.block || '?') +
            (v.title ? ' "' + String(v.title).slice(0, 40) + '"'
              : (v.caption
                ? ' "' + String(v.caption).slice(0, 40) + '"' : ''));
          taskLabel[n] = label;
          if (String(v.type || '') === 'image') {
            if (!v.prompt) {
              artFail[n] = 'image task without prompt';
              continue;
            }
            artImgs.push({ n: n,
              prompt: String(v.prompt).slice(0, 600) });
            continue;
          }
          const ds = v.dataset;
          if (!ds || typeof ds !== 'object' ||
              !ds.data || typeof ds.data !== 'object') {
            artFail[n] = 'chart task without dataset.data';
            continue;
          }
          if (chartBudget <= 0) {
            artFail[n] = 'over media cap ' + MEDIA_MAX;
            continue;
          }
          chartBudget--;
          const vid = String(v.viz_id ||
            ('v' + artSpecs.length + '-' + String(v.block || 'x')))
            .toLowerCase().replace(/[^a-z0-9_-]+/g, '-').slice(0, 40);
          chartSlots.push({ n: n, vid: vid });
          artSpecs.push({ type: String(v.type || ''), viz_id: vid,
            title: String(v.title || '').slice(0, 80),
            caption: String(v.caption || '').slice(0, 200),
            options: (v.options && typeof v.options === 'object')
              ? v.options : undefined });
          artData.push({ id: vid, kind: String(ds.kind || ''),
            title: String(v.title || ds.title || ''),
            unit: ds.unit, data: ds.data });
        }
        // chart batch: the renderer returns paths[] in spec order
        // with the failures listed in skipped[] ({viz_id, reason}),
        // so each slot pairs with the next returned path - a
        // mid-batch failure cannot shift a later chart onto an
        // earlier spec's path. A thrown call fails every chart task.
        if (artSpecs.length) {
          try {
            const rr = await this.helpers.httpRequest({
              method: 'POST', url: VIZ, json: true, timeout: 120000,
              body: { draft_id: itemDraftId, specs: artSpecs,
                viz_data: artData }
            });
            const got = (rr && Array.isArray(rr.paths) ? rr.paths : [])
              .map(String);
            const skipByVid = {};
            for (const s of (rr && Array.isArray(rr.skipped)
              ? rr.skipped : [])) {
              if (s && s.viz_id != null) {
                skipByVid[String(s.viz_id)] =
                  String(s.reason || 'skipped').slice(0, 80);
              }
            }
            let pi = 0;
            for (const slot of chartSlots) {
              if (skipByVid[slot.vid] != null) {
                artFail[slot.n] = skipByVid[slot.vid];
              } else if (pi < got.length) {
                pathByN[slot.n] = got[pi];
                pi++;
              } else {
                artFail[slot.n] = 'no path returned';
              }
            }
            log({ stage: 'viz', role: role, draft_id: itemDraftId,
              source: 'article-visuals', tasks: artSpecs.length,
              rendered: got, skipped: rr && rr.skipped });
          } catch (e) {
            let ed; try { ed = JSON.stringify(e); } catch (_) { ed = String(e); }
            for (const slot of chartSlots) {
              artFail[slot.n] = 'render call failed';
            }
            log({ stage: 'viz', role: role, source: 'article-visuals',
              error: scrubSecrets(ed).slice(0, 400) });
          }
        }
        // image tasks: one /image call each as before, capped at the
        // room the chart successes left under MEDIA_MAX; tasks past
        // the cap are warned about instead of silently sliced away
        const imgRoom = Math.max(0,
          room() - Object.keys(pathByN).length);
        for (let ii = 0; ii < artImgs.length; ii++) {
          const im = artImgs[ii];
          if (ii >= imgRoom) {
            artFail[im.n] = 'over media cap ' + MEDIA_MAX;
            continue;
          }
          try {
            const ir = await this.helpers.httpRequest({
              method: 'POST', url: GW + '/image', json: true,
              timeout: 290000,
              body: { prompt: im.prompt,
                name: itemDraftId + '_art' + im.n }
            });
            if (ir && ir.path) {
              pathByN[im.n] = String(ir.path);
            } else {
              artFail[im.n] = 'image render returned no path';
            }
          } catch (e2) {
            artFail[im.n] = 'image render failed';
            log({ stage: 'image', role: role, draft_id: itemDraftId,
              step: 'render', source: 'article-visuals',
              error: scrubSecrets(e2).slice(0, 300) });
          }
        }
        // final attach order = requested order over the tasks that
        // produced a path; mediaSel.selected only grows from here,
        // so the pushed index IS the figure number the pointers get
        const figMap = {};    // reqN -> final 1-based Fig N
        const figDesc = {};   // final Fig N -> 'type/block "title"'
        for (let vi = 0; vi < artTasks.length; vi++) {
          const n = vi + 1;
          const p = pathByN[n];
          if (p == null) continue;
          if (mediaSel.selected.length >= MEDIA_MAX) {
            artFail[n] = 'over media cap ' + MEDIA_MAX;
            continue;
          }
          mediaSel.selected.push(p);
          figMap[n] = mediaSel.selected.length;
          figDesc[figMap[n]] = taskLabel[n];
        }
        for (const fn0 of Object.keys(artFail)) {
          warnings.push(('fig ' + fn0 + ' render failed: ' +
            (taskLabel[fn0] || '?/?') + ' - ' +
            artFail[fn0]).slice(0, 200));
        }
        if (artTasks.length) {
          const figNotes = Object.keys(figDesc)
            .map((fn2) => 'Fig ' + fn2 + ': ' + figDesc[fn2]);
          if (figNotes.length) {
            mediaSel.caption_note = (mediaSel.caption_note
              ? mediaSel.caption_note + ' | ' : '') +
              'article figs: ' + figNotes.join(', ');
          }
          // rewrite the pointers last of all: surviving figs renumber
          // to their attach index, pointers at failed or unknown figs
          // drop out entirely. One optional space on either side is
          // consumed so a drop leaves 'A B' or 'A.' - never 'AB' or
          // 'A .'; nothing may survive as a pointer to a non-attached
          // image
          const dangling = {};
          text = String(text).replace(
            /( ?)\[(?:(?:see|см\.?)\s*)?fig(?:ure)?s?\.?\s*(\d+)\]( ?)/gi,
            (m, sp1, num, sp2) => {
              const target = figMap[Number(num)];
              if (target != null) {
                return sp1 + m
                  .slice(sp1.length, m.length - sp2.length)
                  .replace(/\d+/, String(target)) + sp2;
              }
              if (artFail[Number(num)] == null) dangling[num] = true;
              return (sp1 && sp2) ? ' ' : '';
            });
          for (const dn of Object.keys(dangling)) {
            warnings.push(('fig ' + dn + ' pointer removed - no ' +
              'matching visuals[] task').slice(0, 200));
          }
          if (parsed) parsed.text = text;
        }
      }
      if (sessionViz) {
        if (vizData.length && room()) {
          try {
            const vsr = await run('viz-spec', JSON.stringify({
              text: text, platform: role.replace('writer-', ''),
              accents: accents, viz_data: vizData
            }));
            const vs = vsr.json || JSON.parse(vsr.text);
            const knownIds = new Set(vizData.map((d) => d && d.id));
            const specs = (Array.isArray(vs.charts) ? vs.charts : [])
              .filter((s) => s && knownIds.has(s.viz_id)).slice(0, room());
            if (specs.length) {
              const rr = await this.helpers.httpRequest({
                method: 'POST', url: VIZ, json: true, timeout: 120000,
                body: { draft_id: itemDraftId, specs: specs, viz_data: vizData }
              });
              mediaSel.selected = mediaSel.selected.concat(
                (rr && Array.isArray(rr.paths) ? rr.paths : [])
                  .map(String)).slice(0, MEDIA_MAX);
              mediaSel.caption_note = (mediaSel.caption_note
                ? mediaSel.caption_note + ' | ' : '') +
                'generated charts: ' +
                specs.map((s) => s.type + '/' + s.viz_id).join(', ') +
                (vs.note ? ' - ' + String(vs.note).slice(0, 150) : '');
            }
            log({ stage: 'viz', role: role, draft_id: itemDraftId,
              datasets: vizData.length, specs: specs.length,
              rendered: mediaSel.selected });
          } catch (e) {
            let ed; try { ed = JSON.stringify(e); } catch (_) { ed = String(e); }
            log({ stage: 'viz', role: role, error: scrubSecrets(ed).slice(0, 400) });
          }
        }
      } else if (genImagePath) {
      // image generation: image-gen emits 1-2 image prompts; each is
      // rendered by the gateway POST /image into materials/img/.
      try {
        const igr = await run('image-gen', JSON.stringify({
          text: text, platform: role.replace('writer-', ''),
          accents: accents, topic: topic
        }));
        const igs = igr.json || JSON.parse(igr.text);
        const imgSpecs = (Array.isArray(igs.images) ? igs.images : [])
          .map((s) => (typeof s === 'string' ? { prompt: s, caption: '' } : s))
          .filter((s) => s && s.prompt).slice(0, room());
        const imgPaths = [];
        for (let k = 0; k < imgSpecs.length; k++) {
          try {
            const ir = await this.helpers.httpRequest({
              method: 'POST', url: GW + '/image', json: true, timeout: 290000,
              body: { prompt: String(imgSpecs[k].prompt), name: itemDraftId + '_' + k }
            });
            if (ir && ir.path) imgPaths.push(String(ir.path));
          } catch (e2) {
            log({ stage: 'image', role: role, draft_id: itemDraftId,
              step: 'render', error: scrubSecrets(e2).slice(0, 300) });
          }
        }
        mediaSel.selected = mediaSel.selected.concat(imgPaths)
          .slice(0, MEDIA_MAX);
        mediaSel.caption_note = (mediaSel.caption_note
          ? mediaSel.caption_note + ' | ' : '') +
          'generated image(s): ' +
          imgSpecs.map((s) => String(s.caption || '')).filter(Boolean).join('; ') +
          (igs.note ? ' - ' + String(igs.note).slice(0, 120) : '');
        log({ stage: 'image', role: role, draft_id: itemDraftId,
          prompts: imgSpecs.length, rendered: mediaSel.selected });
      } catch (e) {
        log({ stage: 'image', role: role, error: scrubSecrets(e).slice(0, 300) });
      }
      } else {
      // media selection: candidates come from payload media[] or
      // a serialized brief's media[] (strings or {path, desc}). The
      // selector matches them against the draft's accents and picks 0-2;
      // an empty selection is valid - the post then goes text-only.
      const mediaCands = (Array.isArray(b.media) ? b.media
        : (Array.isArray(briefMeta.media) ? briefMeta.media : []))
        .map((m) => (typeof m === 'string'
          ? { path: m, desc: '' }
          : { path: String((m && m.path) || ''),
              desc: String((m && (m.desc || m.description)) || '') }))
        .filter((m) => m.path);
      if (mediaCands.length && room()) {
        try {
          const mr = await run('media-selector', JSON.stringify({
            text: text, platform: role.replace('writer-', ''),
            accents: accents, candidates: mediaCands
          }));
          const mp = mr.json || JSON.parse(mr.text);
          const known = new Set(mediaCands.map((c) => c.path));
          mediaSel.selected = mediaSel.selected.concat(
            (Array.isArray(mp.selected) ? mp.selected : [])
              .map(String).filter((p) => known.has(p)))
            .slice(0, MEDIA_MAX);
          const selNote = String(mp.caption_note || '');
          if (selNote) {
            mediaSel.caption_note = (mediaSel.caption_note
              ? mediaSel.caption_note + ' | ' : '') + selNote;
          }
          log({ stage: 'media', role: role, candidates: mediaCands.length,
            selected: mediaSel.selected, note: mediaSel.caption_note });
        } catch (e) {
          log({ stage: 'media', role: role, error: scrubSecrets(e).slice(0, 300) });
        }
      }
      }
    } catch (e) {
      log({ stage: 'write', role: role, error: scrubSecrets(e).slice(0, 300) });
      results.push({ platform: role.replace('writer-', ''), ok: false, stage: 'write', error: scrubSecrets(e).slice(0, 300) });
      continue;
    }

    if (topPerf.length) {
      mediaSel.caption_note = (mediaSel.caption_note
        ? mediaSel.caption_note + ' | ' : '') +
        'perf-informed: ' + topPerf.length + ' top posts';
    }

    // to Telegram moderation
    try {
      const mod = await this.helpers.httpRequest({
        method: 'POST', url: MOD, json: true,
        // explicit timeout like every other helper call in this node:
        // helpers.httpRequest is unbounded by default, so a hung local
        // webhook would stall the whole generation run
        timeout: 30000,
        // moderation-draft is gated by a shared-secret check
        // (X-Shared-Token / X-TG-Draft-Secret vs DRAFT_WEBHOOK_SECRET,
        // see Prepare Draft in sp-tg-moderation) - the gate fails
        // closed, so an unset env here makes every dispatch bounce
        headers: ENV0('DRAFT_WEBHOOK_SECRET')
          ? { 'X-Shared-Token': ENV0('DRAFT_WEBHOOK_SECRET') } : {},
        body: {
          draft_id: itemDraftId,
          // platform is pinned to the dispatch decision encoded in `role`
          // (writer-vk -> vk): it flows into the draft file, the ENABLED
          // gate in Handle TG Update and the sp-publish driver. An LLM
          // self-declared parsed.platform ('vk' in a writer-fb output)
          // would misroute FB-formatted text onto the VK wall, so the
          // model output cannot override routing here
          platform: role.replace('writer-', ''),
          topic: topic, text: text, image: b.image || '', source: 'content-gen',
          // test is a strict JSON boolean end-to-end (Prepare Draft ->
          // queue payload -> publishVk's publish-verify-delete path).
          // An Edit rewrite comes back through this same dispatch, so a
          // missing field would turn a self-deleting test draft into a
          // permanent wall post on Approve
          test: b.test === true,
          scope: scope || undefined,
          warnings: warnings.length ? warnings : undefined,
          media: mediaSel.selected.length ? mediaSel.selected : undefined,
          caption_note: mediaSel.caption_note || undefined,
          // habr-only fields (docs/habr-driver-spec.md): writer-habr's
          // prompt emits kind/title/hubs/tags inside `parsed` next to
          // text - Prepare Draft stamps them into the draft file and
          // Approve snapshots them into the queue payload for the
          // habr driver's content contract. undefined on every other
          // platform keeps the dispatch body byte-identical.
          kind: (parsed && parsed.kind) || undefined,
          title: (parsed && parsed.title) || undefined,
          hubs: (parsed && Array.isArray(parsed.hubs))
            ? parsed.hubs : undefined,
          tags: (parsed && Array.isArray(parsed.tags))
            ? parsed.tags : undefined,
          // post_id rides the dispatch so Prepare Draft stamps it into
          // the draft file - moderation/publish then tag their registry
          // events with it without ever resolving the grouping
          post_id: postId
        }
      });
      // HTTP 200 is not delivery: moderation-draft answers
      // {ok:false} in-band for gate refusals (bad/absent shared
      // secret, overwrite-guard reject, corrupt draft file) and for
      // internal failures like a missing draft file. Treating any
      // resolved response as delivered would silently lose the draft.
      if (!mod || mod.ok !== true) {
        const mErr = 'moderation-draft not accepted: ' +
          String((mod && mod.error) || 'response without ok:true').slice(0, 250);
        log({ stage: 'moderate', role: role, draft_id: itemDraftId,
          ok: false, error: mErr });
        results.push({ platform: role.replace('writer-', ''), ok: false, stage: 'moderate', error: mErr });
        // surface to the operator - a refused draft never reaches
        // Telegram, so nothing else would report the loss
        await notify('draft ' + itemDraftId + ' (' + role +
          ') refused by moderation-draft: ' + mErr.slice(0, 180));
        continue;
      }
      results.push({ platform: role.replace('writer-', ''), ok: true, draft_id: mod.draft_id, warnings: warnings.length });
      // 'delivered' counts roles that actually produced a draft while
      // carrying top performers - 'matched' counts injected entries
      // whether or not the draft survived
      if (topPerf.length) perfDelivered += 1;
      log({ stage: 'moderate', role: role, draft_id: mod.draft_id, warnings: warnings.length });
      // draft file is written and the preview confirmed (mod.ok means
      // the whole Prepare Draft + Compose Message chain succeeded):
      // record the lifecycle event. A rewrite re-dispatch fires the
      // same transition again - the reader's last-occurrence-wins
      // fold lands on the newest draft version
      registryEvent({ post_id: postId, draft_id: mod.draft_id,
        platform: role.replace('writer-', ''),
        stage: 'draft', status: 'pending', writer: 'sp-content-gen' });
    } catch (e) {
      log({ stage: 'moderate', role: role, error: scrubSecrets(e).slice(0, 300) });
      results.push({ platform: role.replace('writer-', ''), ok: false, stage: 'moderate', error: scrubSecrets(e).slice(0, 300) });
    }
  }
}
if (!perfSkip) {
  log({ action: 'perf-summary', posts: perfPosts.length,
    matched: perfMatched, delivered: perfDelivered });
}
return [{ json: { ok: true, results: results } }];
